<script setup lang="ts">
import { Check, FileCode2, FileText, MessageCircle, Minus, Quote, Sparkles, TriangleAlert } from 'lucide-vue-next'
import type { ProductWritingCapsule, ProductWritingCluster, ProductWritingClusterDetail } from '@/types/product'

const props = defineProps<{ cluster: ProductWritingCluster | null; capsule?: ProductWritingCapsule; detail: ProductWritingClusterDetail | null; loading: boolean; filter: string; saving: boolean }>()
const emit = defineEmits<{ accept: []; reject: []; reset: []; 'update:filter': [value: string]; 'load-more': [] }>()
const filters = [
  { key: 'key', label: '关键节点' }, { key: 'user', label: '我的判断' }, { key: 'tutor', label: 'Tutor' },
  { key: 'evidence', label: 'SQL / 证据' }, { key: 'error', label: '错误' }, { key: 'zhihu', label: '知乎来源' },
]
function icon(kind: string) { if (kind === 'user_message') return MessageCircle; if (kind === 'tutor_reply') return Quote; if (kind === 'error') return TriangleAlert; if (kind === 'sql' || kind === 'explain') return FileCode2; return FileText }
function summary(cluster: ProductWritingCluster | null): string { return cluster?.modelSummary || cluster?.ruleSummary || '' }
</script>

<template>
  <aside class="evidence-inspector" aria-label="证据检查器">
    <div v-if="!cluster" class="inspector-empty"><FileText :size="18" aria-hidden="true" /><strong>当前实践还没有可整理的记录</strong><span>完成一次对话或实验后，重新整理证据地图。</span></div>
    <template v-else>
      <header class="inspector-header">
        <div class="inspector-heading"><div><span class="eyebrow">{{ String(cluster.position).padStart(2, '0') }} · EVIDENCE CLUSTER</span><h2>{{ cluster.title }}</h2></div><span class="inspector-state">{{ cluster.status === 'accepted' ? '已纳入文章' : cluster.status === 'rejected' ? '暂不纳入' : '待确认' }}</span></div>
        <p class="inspector-summary">{{ summary(cluster) }}</p>
        <div class="inspector-meta"><span><strong>{{ capsule?.representativeCount ?? 0 }}</strong> 条代表记录</span><span>{{ capsule?.rawCount ?? cluster.memberCount }} 条原始记录</span><span v-if="(capsule?.omittedCount ?? cluster.duplicateCount) > 0">已折叠 {{ capsule?.omittedCount ?? cluster.duplicateCount }} 条重复记录</span><span v-if="cluster.summaryStatus === 'queued' || cluster.summaryStatus === 'running'" class="model-status"><Sparkles :size="12" aria-hidden="true" />摘要润色中</span></div>
        <div v-if="capsule?.keyFindings.length || capsule?.unresolvedQuestions.length" class="capsule-notes"><div v-if="capsule?.keyFindings.length"><span>关键发现</span><ul><li v-for="finding in capsule.keyFindings" :key="finding">{{ finding }}</li></ul></div><div v-if="capsule?.unresolvedQuestions.length"><span>未决问题</span><ul><li v-for="question in capsule.unresolvedQuestions" :key="question">{{ question }}</li></ul></div></div>
        <div class="inspector-guidance"><span>确认边界</span><p>{{ cluster.relevance }}</p></div>
        <footer class="inspector-actions"><button v-if="cluster.status !== 'accepted'" class="primary-button" type="button" :disabled="saving" @click="emit('accept')"><Check :size="14" aria-hidden="true" />纳入文章</button><button v-if="cluster.status === 'accepted'" class="secondary-button" type="button" :disabled="saving" @click="emit('reset')"><Minus :size="14" aria-hidden="true" />恢复待确认</button><button v-if="cluster.status === 'pending'" class="text-button" type="button" :disabled="saving" @click="emit('reject')">暂不纳入</button><button v-if="cluster.status === 'rejected'" class="text-button" type="button" :disabled="saving" @click="emit('reset')">恢复待确认</button></footer>
      </header>
      <div class="filter-strip" role="tablist" aria-label="证据筛选"><button v-for="item in filters" :key="item.key" type="button" :class="{ active: filter === item.key }" :aria-selected="filter === item.key" role="tab" @click="emit('update:filter', item.key)">{{ item.label }}</button></div>
      <div v-if="loading" class="inspector-loading" role="status">正在打开证据…</div>
      <div v-else-if="detail" class="member-list">
        <article v-for="member in detail.members" :key="member.id" class="member-item" :class="member.role"><component :is="icon(member.kind)" :size="14" aria-hidden="true" /><div><div class="member-title"><strong>{{ member.title }}</strong><span>{{ member.role === 'duplicate' ? '重复记录' : member.verificationStatus }}</span></div><p>{{ member.excerpt || '没有可展示的内容' }}</p></div></article>
        <p v-if="detail.members.length === 0" class="inspector-empty compact">这个筛选条件下没有记录。</p>
        <button v-if="detail.nextCursor" class="load-more" type="button" :disabled="loading" @click="emit('load-more')">{{ loading ? '正在加载…' : '加载更多证据' }}</button>
      </div>
    </template>
  </aside>
</template>

<style scoped>
.evidence-inspector { display: flex; flex-direction: column; min-width: 0; min-height: 0; background: #fff; }.inspector-header { flex: 0 0 auto; padding: 22px 28px 19px; border-bottom: 1px solid var(--line); }.inspector-heading { display: flex; align-items: start; justify-content: space-between; gap: 16px; }.inspector-heading h2 { margin: 8px 0 0; color: var(--ink); font: 400 clamp(28px, 3vw, 42px)/1.05 var(--serif); }.inspector-state { flex: 0 0 auto; padding-top: 6px; color: var(--muted); font: 9px var(--mono); }.inspector-summary { max-width: 760px; margin: 18px 0 0; color: #4e5a57; font-size: 15px; line-height: 1.7; }.inspector-meta { display: flex; flex-wrap: wrap; gap: 10px 18px; margin-top: 16px; color: var(--muted); font: 9px var(--mono); }.inspector-meta strong { color: var(--ink); font: 20px var(--serif); }.model-status { display: inline-flex; align-items: center; gap: 5px; color: var(--blue); }.inspector-guidance { max-width: 760px; margin-top: 18px; padding-top: 14px; border-top: 1px solid var(--line); }.inspector-guidance > span { color: var(--blue); font: 9px var(--mono); }.inspector-guidance p { margin: 7px 0 0; color: var(--muted); font-size: 12px; line-height: 1.6; }.inspector-actions { display: flex; align-items: center; gap: 12px; margin-top: 18px; }.inspector-actions button { display: inline-flex; align-items: center; gap: 6px; }.text-button { padding: 5px 0; border: 0; background: transparent; color: var(--muted); font-size: 11px; cursor: pointer; }.text-button:hover { color: var(--blue); }.filter-strip { display: flex; flex: 0 0 auto; gap: 5px; overflow-x: auto; padding: 9px 20px; border-bottom: 1px solid var(--line); background: var(--paper-muted); }.filter-strip button { flex: 0 0 auto; padding: 5px 7px; border: 1px solid transparent; background: transparent; color: var(--muted); font-size: 10px; cursor: pointer; }.filter-strip button:hover, .filter-strip button.active { border-color: #b8c1ec; background: #fff; color: var(--blue); }.member-list { min-height: 0; overflow-y: auto; padding: 4px 0; }.member-item { display: grid; grid-template-columns: 17px minmax(0, 1fr); gap: 9px; padding: 12px 24px; border-bottom: 1px solid var(--line-soft); color: var(--muted); }.member-item svg { margin-top: 2px; color: var(--blue); }.member-item.duplicate { opacity: .62; }.member-title { display: flex; align-items: baseline; gap: 7px; min-width: 0; }.member-title strong { overflow: hidden; color: var(--ink); font-size: 10px; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }.member-title span { flex: 0 0 auto; color: var(--muted); font: 8px var(--mono); }.member-item p { max-height: 90px; overflow: hidden; margin: 5px 0 0; color: #68716d; font: 10px/1.6 var(--sans); white-space: pre-wrap; }.inspector-empty { display: grid; justify-items: center; align-content: center; gap: 8px; min-height: 220px; padding: 40px 20px; color: var(--muted); text-align: center; }.inspector-empty strong { color: var(--ink); font-size: 12px; }.inspector-empty span { max-width: 260px; font-size: 10px; line-height: 1.5; }.inspector-empty.compact { min-height: 100px; }.inspector-loading { padding: 25px; color: var(--muted); font: 10px var(--mono); }
.capsule-notes { display: grid; gap: 10px; margin-top: 16px; padding: 12px 14px; border-left: 2px solid var(--green); background: var(--paper-muted); }.capsule-notes > div { display: grid; gap: 5px; }.capsule-notes span { color: var(--blue); font: 9px var(--mono); }.capsule-notes ul { display: grid; gap: 3px; margin: 0; padding-left: 16px; color: #4e5a57; font-size: 11px; line-height: 1.45; }
.load-more { margin: 10px 15px 14px; padding: 7px; border: 1px solid var(--line); background: var(--paper-muted); color: var(--blue); font-size: 10px; cursor: pointer; }.load-more:disabled { opacity: .6; cursor: wait; }
</style>
